sys_script_include.script:
var IRISPolicyLookup = Class.create();
IRISPolicyLookup.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor, {

        getPolicyDetails: function() {
            var policyValue = this.getParameter(
                'sysparm_policy_sys_id'
            );

            // Fallback for callers still sending the old parameter
            if (!policyValue) {
                policyValue = this.getParameter(
                    'sysparm_policy_number'
                );
            }

            var result = {
                found: false
            };

            if (!policyValue) {
                return JSON.stringify(result);
            }

            var policy = new GlideRecord(
                'x_snc_insurance_0_policy'
            );

            // First, try matching the value as a record sys_id
            if (!policy.get(policyValue)) {
                // If that fails, try matching the policy number
                policy = new GlideRecord(
                    'x_snc_insurance_0_policy'
                );
                policy.addQuery('policy_number', policyValue);
                policy.setLimit(1);
                policy.query();

                if (!policy.next()) {
                    return JSON.stringify(result);
                }
            }

            // Only staff, or the policy's own owner, may see the details
            var isStaff = gs.hasRole('admin') || gs.hasRole('x_snc_insurance_0.policy_user');
            if (!isStaff && policy.getValue('policy_owner') != gs.getUserID()) {
                return JSON.stringify(result);
            }

            result.found = true;
            result.policyholder_name =
                policy.getValue('policyholder_name');
            result.coverage_limit =
                policy.getValue('coverage_limit');
            result.policy_status =
                policy.getValue('policy_status');

            return JSON.stringify(result);
        },

        type: 'IRISPolicyLookup'
    });
